376	                                for points in lines {
377	                                    if points.len() < 2 {
378	                                        continue;
379	                                    }
380	
381	                                    let mut builder = PathBuilder::stroke(px(1.));
382	                                    if dashed {
383	                                        builder = builder.dash_array(&[px(4.), px(2.)]);
384	                                    }
385	                                    for (i, p) in points.into_iter().enumerate() {
386	                                        if i == 0 {
